/**
 * The two pyright config files of the layout contract (docs/analysis/07-linting-stubs.md P.4).
 *   <dot-folder>/pyright.generated.json   environment only: pythonPlatform, ignore, stubPath, extraPaths. Rewritten freely.
 *   pyrightconfig.json                    user-owned, created once with consent, `extends` the generated file, never rewritten.
 * Paths in the generated file are relative to THAT file and use forward slashes only, so the folder roams between macOS and
 * Windows through OneDrive, git or a zip. Rule severities live only in the user-owned file: a child `typeCheckingMode`
 * discards rule overrides of its base (P.2.2 a6), and a child key REPLACES the base key (extraPaths is not merged).
 */
import { parse, type ParseError } from 'jsonc-parser';
import { IDENTITY } from '../identity';

export const GENERATED_NAME = 'pyright.generated.json';
export const USER_CONFIG_NAME = 'pyrightconfig.json';
export const GENERATED_REL = `${IDENTITY.dotDir}/${GENERATED_NAME}`;
/** Keys that, when set in the user-owned file, replace the generated ones. */
export const ENVIRONMENT_KEYS = ['extraPaths', 'stubPath', 'ignore', 'pythonPlatform'] as const;

export interface GeneratedConfig {
  pythonPlatform: string;
  ignore: string[];
  stubPath?: string;
  extraPaths: string[];
}

export function renderGeneratedConfig(cfg: GeneratedConfig): string {
  const body: Record<string, unknown> = { pythonPlatform: cfg.pythonPlatform, ignore: cfg.ignore };
  if (cfg.stubPath !== undefined) { body.stubPath = cfg.stubPath; }
  body.extraPaths = cfg.extraPaths;
  return [
    `// GENERATED by ${IDENTITY.displayName} (IntelliSense setup). Do not edit: it is rewritten when the inputs change.`,
    `// Paths are relative to this file. Put your own settings in ../${USER_CONFIG_NAME}; that file extends this one and is never touched.`,
    JSON.stringify(body, null, 2),
    '',
  ].join('\n');
}

export function renderUserConfig(): string {
  return [
    `// Created by ${IDENTITY.displayName}. This file is yours: the extension never rewrites it.`,
    '{',
    `  "extends": "${GENERATED_REL}",`,
    '  "typeCheckingMode": "basic",',
    '  "reportMissingModuleSource": "none"',
    '  // Do NOT add "extraPaths", "stubPath", "ignore" or "pythonPlatform" here: a key in this file REPLACES the generated one.',
    '  // Rule severities belong here, not in the generated file.',
    '}',
    '',
  ].join('\n');
}

/** What to add to an existing pyrightconfig.json that does not extend ours. */
export function extendsSnippet(): string {
  return `"extends": "${GENERATED_REL}",`;
}

export interface UserConfigAnalysis {
  valid: boolean;
  error?: string;
  extendsValue?: string;
  extendsOurs: boolean;
  /** Environment keys the user file sets itself (they replace the generated values). */
  overridden: string[];
}

function normalizeExtends(v: string): string {
  return v.replace(/\\/g, '/').replace(/^\.\//, '');
}

export function analyzeUserConfig(text: string): UserConfigAnalysis {
  const errors: ParseError[] = [];
  const value = parse(text, errors, { allowTrailingComma: true, disallowComments: false }) as unknown;
  if (errors.length > 0 || typeof value !== 'object' || value === null || Array.isArray(value)) {
    return { valid: false, error: errors.length > 0 ? `JSON error at offset ${errors[0]?.offset ?? 0}` : 'not a JSON object', extendsOurs: false, overridden: [] };
  }
  const obj = value as Record<string, unknown>;
  const ext = obj.extends;
  const out: UserConfigAnalysis = {
    valid: true,
    extendsOurs: typeof ext === 'string' && normalizeExtends(ext) === GENERATED_REL,
    overridden: ENVIRONMENT_KEYS.filter((k) => k in obj),
  };
  if (typeof ext === 'string') { out.extendsValue = ext; }
  return out;
}

/** `[tool.pyright]` in pyproject.toml makes pyright ignore pyrightconfig.json settings it would otherwise merge (P.2.1). */
export function pyprojectHasPyright(text: string): boolean {
  // `[tool.pyright]`, any sub-table such as `[tool.pyright.defineConstant]`, spaces inside the brackets and a quoted key all count
  return /^[ \t]*\[\[?\s*tool\s*\.\s*(?:pyright|"pyright"|'pyright')\s*(?=[.\]])/m.test(text);
}
